48	          Eth2Network.GNOSIS, "gnosis.ssz",
49	          Eth2Network.MAINNET, "mainnet.ssz",
50	          Eth2Network.SEPOLIA, "sepolia.ssz",
51	          Eth2Network.LUKSO, "lukso.ssz",
52	          Eth2Network.HOLESKY, "holesky.ssz");
53	
54	  private static final Logger LOG = LogManager.getLogger();
55	
56	  private final List<DepositSnapshotResource> depositSnapshotResources;
57	
58	  private DepositSnapshotFileLoader(final List<DepositSnapshotResource> resources) {
59	    this.depositSnapshotResources = resources;
60	  }
61	
62	  public LoadDepositSnapshotResult loadDepositSnapshot() {
63	    for (final DepositSnapshotResource resource : depositSnapshotResources) {
64	      final String depositSnapshotResourceUrl = resource.resource;
65	      final String sanitizedUrl = UrlSanitizer.sanitizePotentialUrl(depositSnapshotResourceUrl);
66	      final boolean isRequired = resource.required;
67	
68	      try {
69	        STATUS_LOG.loadingDepositSnapshotResource(sanitizedUrl);
70	        final DepositTreeSnapshot depositTreeSnapshot = loadFromUrl(depositSnapshotResourceUrl);
71	        // Validate
72	        DepositTree.fromSnapshot(depositTreeSnapshot);
73	        STATUS_LOG.onDepositSnapshot(
74	            depositTreeSnapshot.getDepositCount(), depositTreeSnapshot.getExecutionBlockHash());
75	        return LoadDepositSnapshotResult.create(Optional.of(depositTreeSnapshot));
76	      } catch (final Exception e) {
77	        if (e instanceof IllegalArgumentException) {
78	          LOG.warn(
79	              "Deposit tree snapshot loaded from " + sanitizedUrl + " is not a correct snapshot",
80	              e);
81	        } else {
82	          LOG.warn("Failed to load deposit tree snapshot from " + sanitizedUrl, e.getMessage());
83	        }
84	
85	        if (isRequired) {
86	          throw new InvalidConfigurationException(
87	              "Failed to load deposit tree snapshot from " + sanitizedUrl + ": " + e.getMessage());
88	        }
89	      }
90	    }
91	
92	    return LoadDepositSnapshotResult.empty();
93	  }
94	
95	  private DepositTreeSnapshot loadFromUrl(final String path) throws IOException {
96	    final Bytes snapshotData =
97	        ResourceLoader.urlOrFile("application/octet-stream, application/json")
98	            .loadBytes(path)
99	            .orElseThrow(
100	                () ->
101	                    new FileNotFoundException(
102	                        String.format("Failed to load deposit tree snapshot from %s", path)));
103	
104	    try {
105	      return parseSszDepositSnapshotTreeData(snapshotData);
106	    } catch (final SszDeserializeException e) {
107	      return parseJsonDepositSnapshotTreeData(snapshotData);
108	    }
109	  }
110	
111	  private static DepositTreeSnapshot parseSszDepositSnapshotTreeData(final Bytes snapshotData) {
112	    return DepositTreeSnapshot.fromBytes(snapshotData);
113	  }
114	
115	  private static DepositTreeSnapshot parseJsonDepositSnapshotTreeData(final Bytes snapshotData)
116	      throws JsonProcessingException {
117	    final String json = new String(snapshotData.toArray(), StandardCharsets.UTF_8);
118	    final JsonNode jsonNode = new ObjectMapper().readTree(json);
119	    return JsonUtil.parse(
120	        jsonNode.get("data").toString(), DepositTreeSnapshot.getJsonTypeDefinition());
121	  }
122	
123	  @VisibleForTesting
124	  public List<DepositSnapshotResource> getDepositSnapshotResources() {
125	    return depositSnapshotResources;
126	  }
