86	      final PowchainConfiguration powConfig,
87	      final Optional<ExecutionWeb3jClientProvider> maybeExecutionWeb3jClientProvider,
88	      final Supplier<Optional<BeaconState>> finalizedStateSupplier) {
89	    checkArgument(powConfig.isEnabled() || maybeExecutionWeb3jClientProvider.isPresent());
90	    this.serviceConfig = serviceConfig;
