96	  @Override
97	  protected SafeFuture<?> doStart() {
98	    if (isFormerDepositMechanismDisabled()) {
99	      // no need to initialize and start services if Eth1 polling has already been disabled
100	      return SafeFuture.COMPLETE;
101	    }
102	    return SafeFuture.fromRunnable(this::initialize)
103	        .thenPeek(__ -> hasInitialized.set(true))
104	        .thenCompose(
105	            __ ->
106	                SafeFuture.allOfFailFast(
107	                    SafeFuture.fromRunnable(headTracker::start),
108	                    SafeFuture.fromRunnable(eth1DepositManager::start),
109	                    SafeFuture.fromRunnable(eth1Providers::start)));
110	  }
111	
112	  @Override
113	  protected SafeFuture<?> doStop() {
114	    if (!hasInitialized.get()) {
115	      return SafeFuture.COMPLETE;
116	    }
117	    return SafeFuture.allOfFailFast(
118	        Stream.concat(
119	                Stream.<ExceptionThrowingRunnable>of(
120	                    headTracker::stop,
121	                    eth1DepositManager::stop,
122	                    eth1Providers::stop,
123	                    // stop all tasks currently running
124	                    asyncRunner::shutdown),
125	                web3js.stream().map(web3j -> web3j::shutdown))
126	            .map(SafeFuture::fromRunnable)
127	            .toArray(SafeFuture[]::new));
128	  }
