132	      final Checkpoint checkpoint, final boolean fromOptimisticBlock) {
133	    if (!isRunning()) {
134	      return;
135	    }
136	    if (isFormerDepositMechanismDisabled()) {
137	      //  stop Eth1 polling
138	      stop()
139	          .finish(
140	              () -> {
141	                if (hasInitialized.get()) {
142	                  // only log if polling has been enabled and now stopped
143	                  STATUS_LOG.eth1PollingHasBeenDisabled();
144	                }
145	              },
146	              LOG::error);
147	    }
148	  }
