159	    asyncRunner = serviceConfig.createAsyncRunner("powchain");
160	
161	    final SpecConfig config = powConfig.getSpec().getGenesisSpecConfig();
162	    if (!powConfig.isEnabled()) {
163	      final ExecutionWeb3jClientProvider executionWeb3jClientProvider =
164	          maybeExecutionWeb3jClientProvider.orElseThrow();
165	      if (executionWeb3jClientProvider.getWeb3JClient().isWebsocketsClient()) {
166	        throw new InvalidConfigurationException(
167	            "Eth1 endpoint fallback is not compatible with Websockets execution engine endpoint");
