41	public class DepositSnapshotFileLoader {
42	
43	  public record DepositSnapshotResource(String resource, boolean required) {}
44	
45	  public static final Map<Eth2Network, String> DEFAULT_SNAPSHOT_RESOURCE_PATHS =
46	      Map.of(
47	          Eth2Network.GNOSIS, "gnosis.ssz",
48	          Eth2Network.PRATER, "goerli.ssz",
49	          Eth2Network.MAINNET, "mainnet.ssz",
50	          Eth2Network.SEPOLIA, "sepolia.ssz",
51	          Eth2Network.LUKSO, "lukso.ssz",
52	          Eth2Network.HOLESKY, "holesky.ssz");
53	
54	  private static final Logger LOG = LogManager.getLogger();
55	
56	  private final List<DepositSnapshotResource> depositSnapshotResources;
57	
58	  private DepositSnapshotFileLoader(final List<DepositSnapshotResource> resources) {
59	    this.depositSnapshotResources = resources;
60	  }
61	
62	  public LoadDepositSnapshotResult loadDepositSnapshot() {
63	    for (final DepositSnapshotResource resource : depositSnapshotResources) {
64	      final String depositSnapshotResourceUrl = resource.resource;
65	      final String sanitizedUrl = UrlSanitizer.sanitizePotentialUrl(depositSnapshotResourceUrl);
66	      final boolean isRequired = resource.required;
67	
68	      try {
69	        STATUS_LOG.loadingDepositSnapshotResource(sanitizedUrl);
70	        final DepositTreeSnapshot depositTreeSnapshot = loadFromUrl(depositSnapshotResourceUrl);
71	        STATUS_LOG.onDepositSnapshot(
72	            depositTreeSnapshot.getDepositCount(), depositTreeSnapshot.getExecutionBlockHash());
73	        return LoadDepositSnapshotResult.create(Optional.of(depositTreeSnapshot));
74	      } catch (final Exception e) {
75	        LOG.warn("Failed to load deposit tree snapshot from " + sanitizedUrl, e);
76	
77	        if (isRequired) {
78	          throw new InvalidConfigurationException(
79	              "Failed to load deposit tree snapshot from " + sanitizedUrl + ": " + e.getMessage());
80	        }
81	      }
82	    }
83	
84	    return LoadDepositSnapshotResult.empty();
85	  }
86	
87	  private DepositTreeSnapshot loadFromUrl(final String path) throws IOException {
88	    final Bytes snapshotData =
89	        ResourceLoader.urlOrFile("application/octet-stream, application/json")
90	            .loadBytes(path)
91	            .orElseThrow(
92	                () -> new FileNotFoundException(String.format("File '%s' not found", path)));
93	
94	    try {
95	      return parseSszDepositSnapshotTreeData(snapshotData);
96	    } catch (final SszDeserializeException e) {
97	      return parseJsonDepositSnapshotTreeData(snapshotData);
98	    }
99	  }
100	
101	  private static DepositTreeSnapshot parseSszDepositSnapshotTreeData(final Bytes snapshotData) {
102	    return DepositTreeSnapshot.fromBytes(snapshotData);
103	  }
104	
105	  private static DepositTreeSnapshot parseJsonDepositSnapshotTreeData(final Bytes snapshotData)
106	      throws JsonProcessingException {
107	    final String json = new String(snapshotData.toArray(), StandardCharsets.UTF_8);
108	    final JsonNode jsonNode = new ObjectMapper().readTree(json);
109	    return JsonUtil.parse(
110	        jsonNode.get("data").toString(), DepositTreeSnapshot.getJsonTypeDefinition());
111	  }
112	
113	  @VisibleForTesting
114	  public List<DepositSnapshotResource> getDepositSnapshotResources() {
115	    return depositSnapshotResources;
116	  }
117	
118	  public static class Builder {
119	    private final List<DepositSnapshotResource> resources = new ArrayList<>();
120	
121	    public Builder addRequiredResource(final String resource) {
122	      this.resources.add(new DepositSnapshotResource(resource, true));
123	      return this;
124	    }
125	
126	    public Builder addOptionalResource(final String resource) {
127	      this.resources.add(new DepositSnapshotResource(resource, false));
128	      return this;
129	    }
130	
131	    public DepositSnapshotFileLoader build() {
132	      return new DepositSnapshotFileLoader(resources);
133	    }
134	  }
135	}
