21	public class LoadDepositSnapshotResult implements Comparable<LoadDepositSnapshotResult> {
22	  public static final LoadDepositSnapshotResult EMPTY =
23	      new LoadDepositSnapshotResult(Optional.empty(), ReplayDepositsResult.empty());
24	
25	  private final Optional<DepositTreeSnapshot> depositTreeSnapshot;
26	
27	  private final ReplayDepositsResult replayDepositsResult;
28	
29	  public LoadDepositSnapshotResult(
30	      final Optional<DepositTreeSnapshot> depositTreeSnapshot,
31	      final ReplayDepositsResult replayDepositsResult) {
32	    this.depositTreeSnapshot = depositTreeSnapshot;
33	    this.replayDepositsResult = replayDepositsResult;
34	  }
35	
36	  public static LoadDepositSnapshotResult create(
37	      final Optional<DepositTreeSnapshot> depositTreeSnapshot) {
38	    if (depositTreeSnapshot.isEmpty() || depositTreeSnapshot.get().getDepositCount() == 0) {
39	      return LoadDepositSnapshotResult.EMPTY;
40	    } else {
41	      return new LoadDepositSnapshotResult(
42	          depositTreeSnapshot,
43	          ReplayDepositsResult.create(
44	              depositTreeSnapshot.get().getExecutionBlockHeight().bigIntegerValue(),
45	              BigInteger.valueOf(depositTreeSnapshot.get().getDepositCount() - 1),
46	              true));
47	    }
48	  }
49	
50	  public Optional<DepositTreeSnapshot> getDepositTreeSnapshot() {
51	    return depositTreeSnapshot;
52	  }
53	
54	  public ReplayDepositsResult getReplayDepositsResult() {
55	    return replayDepositsResult;
56	  }
57	
58	  @Override
59	  public int compareTo(final LoadDepositSnapshotResult o) {
60	    return replayDepositsResult
61	        .getLastProcessedBlockNumber()
62	        .subtract(o.replayDepositsResult.getLastProcessedBlockNumber())
63	        .signum();
64	  }
65	
66	  @Override
67	  public boolean equals(final Object o) {
68	    if (this == o) {
69	      return true;
70	    }
71	    if (o == null || getClass() != o.getClass()) {
72	      return false;
73	    }
74	    final LoadDepositSnapshotResult that = (LoadDepositSnapshotResult) o;
75	    return Objects.equals(depositTreeSnapshot, that.depositTreeSnapshot)
76	        && Objects.equals(replayDepositsResult, that.replayDepositsResult);
77	  }
78	
79	  @Override
80	  public int hashCode() {
81	    return Objects.hash(depositTreeSnapshot, replayDepositsResult);
82	  }
83	}
