34	    // Note services will be started in the order they are added here.
35	    services.add(
36	        new StorageService(
37	            serviceConfig,
38	            tekuConfig.storageConfiguration(),
39	            tekuConfig.powchain().isDepositSnapshotEnabled(),
40	            tekuConfig.metricsConfig().isBlobSidecarsStorageCountersEnabled()));
41	    Optional<ExecutionWeb3jClientProvider> maybeExecutionWeb3jClientProvider = Optional.empty();
42	    if (tekuConfig.executionLayer().isEnabled()) {
43	      // Need to make sure the execution engine is listening before starting the beacon chain
44	      ExecutionLayerService executionLayerService =
45	          ExecutionLayerService.create(serviceConfig, tekuConfig.executionLayer());
46	      services.add(executionLayerService);
47	      maybeExecutionWeb3jClientProvider = executionLayerService.getEngineWeb3jClientProvider();
48	    }
49	    services.add(new BeaconChainService(serviceConfig, tekuConfig.beaconChain()));
50	    services.add(
51	        new NatService(
52	            tekuConfig.natConfiguration(),
53	            tekuConfig.network().getListenPort(),
54	            tekuConfig.discovery().isDiscoveryEnabled()));
55	    powchainService(tekuConfig, serviceConfig, maybeExecutionWeb3jClientProvider)
56	        .ifPresent(services::add);
57	
58	    final Optional<SlashingRiskAction> maybeValidatorSlashedAction =
59	        tekuConfig.validatorClient().getValidatorConfig().isShutdownWhenValidatorSlashedEnabled()
60	            ? Optional.of(new SlashedValidatorShutDown())
61	            : Optional.empty();
62	
63	    services.add(
64	        ValidatorClientService.create(
65	            serviceConfig,
66	            tekuConfig.validatorClient(),
67	            new DoppelgangerDetectionShutDown(),
68	            maybeValidatorSlashedAction));
69	  }
70	
71	  private Optional<PowchainService> powchainService(
72	      final TekuConfiguration tekuConfig,
73	      final ServiceConfig serviceConfig,
74	      final Optional<ExecutionWeb3jClientProvider> maybeExecutionWeb3jClientProvider) {
75	    if (tekuConfig.beaconChain().interopConfig().isInteropEnabled()
76	        || (!tekuConfig.powchain().isEnabled() && maybeExecutionWeb3jClientProvider.isEmpty())) {
77	      return Optional.empty();
78	    }
79	
80	    return Optional.of(
81	        new PowchainService(
82	            serviceConfig, tekuConfig.powchain(), maybeExecutionWeb3jClientProvider));
83	  }
84	}
