15	
16	import java.net.MalformedURLException;
17	import java.net.URI;
18	import java.net.URISyntaxException;
19	import java.net.URL;
20	import org.apache.commons.lang3.StringUtils;
21	
22	public class UrlSanitizer {
23	
24	  public static String sanitizePotentialUrl(final String possibleUrl) {
25	    try {
26	      final URI uri = new URI(possibleUrl);
27	      return sanitizeUri(uri).toASCIIString();
28	    } catch (final URISyntaxException e) {
29	      // Not actually a URI so no need to sanitize
30	      return possibleUrl;
31	    }
32	  }
33	
34	  public static URL sanitizeUrl(final URL url) {
35	    try {
36	      final URI sanitizedUri = sanitizeUri(url.toURI());
37	      return sanitizedUri.toURL();
38	    } catch (final URISyntaxException | MalformedURLException e) {
39	      // can't sanitize, so will just return the method argument
40	      return url;
41	    }
42	  }
43	
44	  public static String appendPath(final String url, final String path) {
45	    if (StringUtils.isEmpty(url)) {
46	      throw new IllegalArgumentException("Base URL cannot be null/empty");
47	    }
48	
49	    final String sanitizedPath = path == null ? "" : path;
50	    final URL urlWithPath;
51	    try {
52	      urlWithPath = new URL(new URL(url), sanitizedPath);
53	    } catch (MalformedURLException e) {
54	      throw new IllegalArgumentException("Invalid URL " + url, e);
55	    }
56	
57	    return urlWithPath.toString();
58	  }
59	
60	  public static boolean urlContainsNonEmptyPath(final String url) {
61	    try {
62	      final URI uri = new URI(url);
63	      return uri.getPath() != null && uri.getPath().length() > 1;
64	    } catch (URISyntaxException e) {
65	      return false;
66	    }
67	  }
68	
69	  private static URI sanitizeUri(final URI uri) throws URISyntaxException {
70	    return new URI(
71	        uri.getScheme(),
72	        null,
73	        uri.getHost(),
74	        uri.getPort(),
75	        uri.getPath(),
76	        uri.getQuery(),
77	        uri.getFragment());
78	  }
79	}
