import picocli.CommandLine.Option;
import tech.pegasys.teku.config.TekuConfiguration;
import tech.pegasys.teku.services.powchain.PowchainConfiguration;

public class DepositOptions {

  @Option(
      names = {"--eth1-endpoints", "--eth1-endpoint"},
      paramLabel = "<NETWORK>",
      description = "URLs for Eth1 nodes.",
      split = ",",
      arity = "1..*")
  private List<String> eth1Endpoints = new ArrayList<>();

  @Option(
      names = {"--eth1-deposit-contract-max-request-size"},
      paramLabel = "<INTEGER>",
      description =
          "Maximum number of blocks to request deposit contract event logs for in a single request.",
      arity = "1")
  private int eth1LogsMaxBlockRange = PowchainConfiguration.DEFAULT_ETH1_LOGS_MAX_BLOCK_RANGE;

  @Option(
      names = {"--Xeth1-missing-deposits-event-logging-enabled"},
      paramLabel = "<BOOLEAN>",
      description = "Enable logging an event on each slot whenever deposits are missing",
      hidden = true,
      showDefaultValue = Visibility.ALWAYS,
      arity = "0..1",
      fallbackValue = "true")
  private boolean useMissingDepositEventLogging =
      PowchainConfiguration.DEFAULT_USE_MISSING_DEPOSIT_EVENT_LOGGING;

  @CommandLine.Option(
      names = {"--Xdeposit-snapshot"},
      paramLabel = "<STRING>",
      description =
          "Deposit tree snapshot. This value should be a file or URL pointing to a SSZ-encoded or JSON finalized deposit tree snapshot.",
      hidden = true,
      arity = "1")
  private String depositSnapshotPath;

  @Option(
      names = {"--deposit-snapshot-enabled"},
      paramLabel = "<BOOLEAN>",
      description = "Use bundled snapshot for most networks and persist deposit tree snapshot",
      showDefaultValue = Visibility.ALWAYS,
      arity = "0..1",
      fallbackValue = "true")
  private boolean depositSnapshotEnabled = PowchainConfiguration.DEFAULT_DEPOSIT_SNAPSHOT_ENABLED;

  public void configure(final TekuConfiguration.Builder builder) {
    builder.powchain(
        b ->
            b.eth1Endpoints(eth1Endpoints)
                .eth1LogsMaxBlockRange(eth1LogsMaxBlockRange)
                .useMissingDepositEventLogging(useMissingDepositEventLogging)
                .depositSnapshotPath(depositSnapshotPath)
                .depositSnapshotEnabled(parseDepositSnapshotEnabled()));
  }

  private boolean parseDepositSnapshotEnabled() {
    return depositSnapshotEnabled;
  }
}
